examples:
TypeScript progressive example:

const session = Redwood.invoke({ model: 'redwood-alpha', streaming: true, toolRegistry: tools });
for await (const event of session.stream()) {
  if (event.type === 'tool_call') {
    // typed envelope: { id, tool, args, meta }
    const res = await tools.invoke(event.tool, event.args);
    await session.sendToolResult(event.id, res);
  }
  if (event.type === 'delta') {
    ui.append(event.delta);
  }
}

// Also support node ReadableStream and browser-friendly streams via session.toReadable()

Go progressive example:

ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
defer cancel()
stream := client.InvokeStream(ctx, InvokeOpts{Model: 'redwood-alpha', Streaming: true})
for ev := range stream.Events() {
  switch ev.Kind {
  case EventToolCall:
    go func(e Event) {
      res, _ := tools.Invoke(e.Tool, e.Args)
      stream.SendToolResult(e.ID, res)
    }(ev)
  case EventDelta:
    out.Write([]byte(ev.Delta))
  }
}

